// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt) public {
        vm.assume(depositAmt > 0 && withdrawAmt > 0 && withdrawAmt <= depositAmt);
        Reverter reverter = new Reverter();
        vm.deal(address(reverter), 0);
        vm.prank(address(reverter));
        vm.deal(address(reverter), depositAmt);
        (bool sent,) = address(c).call{value: depositAmt}("");
        require(sent, "deposit failed");

        uint256 balBefore = c.balances(address(reverter));
        vm.prank(address(reverter));
        try c.withdraw() { } catch {}

        uint256 balAfter = c.balances(address(reverter));
        assertTrue(balBefore == balAfter);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
